def standard():
    from itertools import product
    tot = fav = 0
    for seq in product(range(1, 7), repeat=3):
        vis = [1]*5
        for k in seq:
            if k <= 5:
                vis[k-1] ^= 1
        if sum((i+1)*x for i, x in enumerate(vis)) % 2 == 0:
            tot += 1
            fav += 6 not in seq
    v = Fraction(fav, tot)
    return v.numerator + v.denominator

def unique():
    return [standard()]
